// Literal port of the team's Casa3DSDK (module furniture/api). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installFurnitureApi(K: Kernel, _shared: Shared): void {
  const { _e, _h2, _q, boxC, cursor, macroGround, polyFace, put } = K;
  // ---------------- 20 furniture ----------------
  // ===== furniture: adapter of the Moveis3DSDK + builders ported from the game (26-casa.js) and generic families =====
  const MATERIAL_MAP = { plain: 'plain', metal: 'metal', wood: 'wood', glass: 'glass', fabric: 'fabric', plant: 'plant', water: 'water', emissive: 'emissive', 'atlas_picture': 'picture', 'atlas_floor': 'floor', plaster: 'plain', matte: 'glass', glass_light: 'emissive', light: 'emissive', ceramic_tile: 'plain', parquet: 'plain', ceramic: 'plain' };
  const mm = k => MATERIAL_MAP[k] || 'plain';
  const LIGHTS = [];
   // real lights requested by the builders: {x,y,z,color,range,type,floor}
  function makeApi() {
    const loc = (M, lx, lz) => { const c = Math.cos(M.ry), s = Math.sin(M.ry); return [M.x + lx * c + lz * s, M.z - lx * s + lz * c]; };
    return {
      box(M, mat, x, y, z, w, h, d, color, ry = 0, rx = 0, rz = 0) { const [px, pz] = loc(M, x, z); boxC(mm(mat), px, M.base + y + h / 2, pz, w, h, d, color, rx, M.ry + ry, rz); },
      cylinder(M, mat, x, y, z, r, h, color, rx = 0, rz = 0, seg) { const [px, pz] = loc(M, x, z); _q.setFromEuler(_e.set(rx || 0, M.ry, rz || 0, 'YXZ')); put(mm(mat), seg || 'cyl', px, M.base + y + ((rx || rz) ? 0 : h / 2), pz, _q, r * 2, h, r * 2, color); },
      leaf(M, x, y, z, w, h, color, ry = 0, rx = 0) { // 3D leaf: curved rib and two folded flaps in a V (no flat plane seen from the side)
        const [px, pz] = loc(M, x, z), a = M.ry + (ry || 0), ca = Math.cos(a), sa = Math.sin(a), t1 = (rx || 0) * 0.8, t2 = (rx || 0) * 1.5, y0 = M.base + y;
        const P = (lx, ly, lz) => [px + lx * ca + lz * sa, y0 + ly, pz - lx * sa + lz * ca];
        const my = Math.cos(t1) * h * 0.5, mz = Math.sin(t1) * h * 0.5, ty = my + Math.cos(t2) * h * 0.5, tz = mz + Math.sin(t2) * h * 0.5, f = w * 0.5, dn = f * 0.32;
        const B = P(0, 0, 0), Mi = P(0, my + 0.004, mz), T = P(0, ty, tz), L = P(-f, my - dn, mz - dn * 0.3), R = P(f, my - dn, mz - dn * 0.3);
        polyFace('plant', [B, L, T, Mi], color, [0, 1, 0]); polyFace('plant', [B, Mi, T, R], sh(color, 0.92), [0, 1, 0]);
      },
      plane(M, mat, x, y, z, w, h, color, ry = 0, rx = 0, rz = 0, uv) {
        const [px, pz] = loc(M, x, z); _q.setFromEuler(_e.set(rx || 0, M.ry + (ry || 0), rz || 0, 'YXZ'));
        if (uv && mat === 'atlas_floor') { // atlas floor: random rotation/mirror per patch and macro colour variation (soil and lawn) to break the repetition
          const col = Math.floor(uv.u0 * 4 + 1e-6), lin = uv.v0 < 0.5 ? 1 : 0, cell = col + 4 * lin, h0 = _h2(Math.round(px * 8), Math.round(pz * 8)), type = cell === 5 ? 'dirt' : (cell === 0 || cell === 1) ? 'lawn' : null;
          if (type === 'dirt') { put('dirt', 'plane', px, M.base + y, pz, _q, w, h, 1, sh(color, 1 / 0.965)); return; } // R46: soil with world UV and noise in the shader (no 2 m atlas cells)
          if (type) uv = { u0: uv.u0, u1: uv.u1, v0: uv.v0, v1: uv.v1, rot: (h0 * 4) | 0, fx: h0 > 0.5 ? 1 : 0, vc: (wx, wz) => macroGround(wx, wz, type) };
        }
        put(mm(mat), 'plane', px, M.base + y, pz, _q, w, h, 1, color, uv);
      },
      light(M, x, y, z, color, range, type, ex) { const [px, pz] = loc(M, x, z); LIGHTS.push(Object.assign({ x: px, y: M.base + y, z: pz, color, range, type, floor: M.floor, group: cursor.group, base: M.base, room: M.room, id: M.lampId }, ex || null)); },
    };
  }
  const sh = (c, f) => { const r = Math.min(255, ((c >> 16) & 255) * f) | 0, g = Math.min(255, ((c >> 8) & 255) * f) | 0, b = Math.min(255, (c & 255) * f) | 0; return (r << 16) | (g << 8) | b; };
  const paletteColor = (M, k, d) => (M.palette && M.palette[k] != null ? M.palette[k] : d);
  function rngOf(M) { let s = (Math.round((M.x || 0) * 37 + (M.z || 0) * 91 + 1000) >>> 0) || 7; return () => (s = (s * 16807) % 2147483647) / 2147483647; }
  // shortcuts: lb = box, lc = cylinder; they add M.y (mounting height) to everything
  function kk(M, A) { const y0 = M.y || 0; return { b: (mat, x, y, z, w, h, d, color, ry, rx, rz) => A.box(M, mat, x, y0 + y, z, w, h, d, color, ry || 0, rx || 0, rz || 0), c: (mat, x, y, z, r, h, color, rx, rz, seg) => A.cylinder(M, mat, x, y0 + y, z, r, h, color, rx || 0, rz || 0, seg), rnd: rngOf(M), wood: paletteColor(M, 'wood', 0x7a5434), met: paletteColor(M, 'metal', 0x9a9ea2) }; }
  const PE = Math.PI / 2;
  Object.assign(K, { MATERIAL_MAP, mm, LIGHTS, makeApi, sh, paletteColor, rngOf, kk, PE });
}
